# Homebrew cask for Swarmfile — generated by installers/packaging/gen-manifests.mjs.
# Do not hand-edit in the tap; re-generate on each release.
#
# auto_updates true: the tray self-updates via tauri-plugin-updater, so brew
# must not treat a self-updated app as needing a "downgrade" back to this
# pinned version. See installers/packaging/README.md.
cask "swarmfile" do
  version "0.3.15"
  sha256 "ec425438ccd79b3d186c7697261854b3d6f526b0b8ead152666b5b8ffca55bab"

  url "https://releases.swarmfile.com/v#{version}/Swarmfile-#{version}.pkg"
  name "Swarmfile"
  desc "Cloud-streamed virtual filesystem for teams working with very large files"
  homepage "https://swarmfile.com"

  auto_updates true
  depends_on macos: :big_sur

  # The universal, notarized .pkg bundles the FUSE-T mount helper, the engine,
  # the tray, and the LaunchAgents — no separate macFUSE/FUSE-T install needed.
  pkg "Swarmfile-#{version}.pkg"

  uninstall pkgutil:   "dev.swarmfile",
            launchctl: [
              "dev.swarmfile.engine",
              "dev.swarmfile.tray",
            ],
            quit:      "dev.swarmfile.tray"

  zap trash: [
    "~/Library/Application Support/dev.swarmfile.tray",
    "~/Library/Caches/dev.swarmfile.tray",
    "~/Library/Preferences/dev.swarmfile.tray.plist",
    "~/Library/Logs/dev.swarmfile.tray",
  ]
end
